    // 0101|L=x|B=x|H=x|Rm=xxx|Rn=xxx|Rt=xxx
    let Rt: u8 = (bits & 0x7) as u8;
    let Rn: u8 = ((bits >> 3) & 0x7) as u8;
    let Rm: u8 = ((bits >> 6) & 0x7) as u8;
